// bioage-dashboard — сборка JSON для вкладки «Биологический возраст». Пишет в Static Data.
// Источники (по имени ноды): Get Results, Get Markers, Get Visits (книга phenoage) + Get PhenoAge_Log (Health_DB).
// Формула: Levine 2018, CRP в мг/л (как в PhenoAge Calc). Run Once for All Items.

const FORMULA_VERSION = 'Levine2018 / CRP=mg/L / 2026-09';

function safeAll(name) { try { return $(name).all().map(i => i.json); } catch (e) { return []; } }
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(String(v).replace(/\s/g, '').replace(',', '.'));
  return isNaN(n) ? null : n;
}
function d10(v) {
  let s = String(v == null ? '' : v).trim();
  let m = s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/);
  if (m) return m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  m = s.match(/^(\d{4})[.\/-](\d{1,2})[.\/-](\d{1,2})/);
  if (m) return m[1] + '-' + m[2].padStart(2, '0') + '-' + m[3].padStart(2, '0');
  return s.slice(0, 10);
}
function decYear(iso) {
  if (!iso || iso.length < 10) return null;
  const y = +iso.slice(0, 4), mo = +iso.slice(5, 7), d = +iso.slice(8, 10);
  return Math.round((y + ((mo - 1) * 30 + d) / 365) * 100) / 100;
}

const results = safeAll('Get Results');
const markers = safeAll('Get Markers');
const visits  = safeAll('Get Visits');
const phenoLog = safeAll('Get PhenoAge_Log');

// 9 маркеров PhenoAge
const PHENO = {
  alb:   { id: 'M008', rx: /альбумин/i, label: 'Альбумин' },
  creat: { id: 'M004', rx: /креатинин/i, label: 'Креатинин' },
  gluc:  { id: 'M003', rx: /глюкоза/i, label: 'Глюкоза' },
  crp:   { id: 'M024', rx: /с-реактивн|срб|crp/i, label: 'CRP (С-реактивный белок)' },
  lymph: { id: 'M062', rx: /лимфоциты\s*%/i, label: 'Лимфоциты %' },
  mcv:   { id: 'M043', rx: /mcv|средний объ[её]м эритроцит/i, label: 'MCV' },
  rdw:   { id: 'M049', rx: /rdw|ширина распред.*эритроцит/i, label: 'RDW' },
  alp:   { id: 'M017', rx: /щелочн(ая)? фосфатаз|alp|щф/i, label: 'Щелочная фосфатаза' },
  wbc:   { id: 'M039', rx: /лейкоциты|wbc/i, label: 'Лейкоциты (WBC)' },
};
const REF = { alb: 47, creat: 75, gluc: 4.6, crp: 0.5, lymph: 33, mcv: 88, rdw: 12.5, alp: 60, wbc: 5 };
const KEYS = Object.keys(PHENO);

const markById = {};
markers.forEach(m => { if (m.Marker_ID) markById[m.Marker_ID] = m; });
function keyForId(mid) {
  for (const [k, def] of Object.entries(PHENO)) {
    if (def.id === mid) return k;
    if (def.rx.test((markById[mid] || {}).Name || '')) return k;
  }
  return null;
}

// visit -> {date, age, values:{key:val}}
const visitMap = {};
visits.forEach(v => { visitMap[v.Visit_ID] = { vid: v.Visit_ID, date: d10(v.Date), age: num(v.Age_at_Visit), values: {} }; });
const visitDate = {}; visits.forEach(v => { if (v.Visit_ID) visitDate[v.Visit_ID] = d10(v.Date); });
for (const r of results) {
  const k = keyForId(r.Marker_ID);
  const val = num(r.Value);
  if (val == null) continue;
  if (!visitMap[r.Visit_ID]) visitMap[r.Visit_ID] = { vid: r.Visit_ID, date: visitDate[r.Visit_ID] || d10(r.Visit_ID), age: null, values: {} };
  if (k) visitMap[r.Visit_ID].values[k] = val;
}

let ageAnchor = null;
Object.values(visitMap).filter(v => v.date && v.age != null)
  .sort((a, b) => a.date.localeCompare(b.date))
  .forEach(v => { ageAnchor = { date: v.date, age: v.age }; });
function ageAtDate(dateStr) {
  if (ageAnchor && dateStr) {
    const dd = (new Date(dateStr) - new Date(ageAnchor.date)) / (365.25 * 86400000);
    return Math.round((ageAnchor.age + dd) * 10) / 10;
  }
  const y = parseInt((dateStr || '').slice(0, 4), 10);
  return isNaN(y) ? null : (y - 1982);
}

function phenoAge(x) {
  const lnCRP = Math.log(Math.max(x.crp, 1e-4));
  const xb = -19.907
    - 0.0336 * x.alb + 0.0095 * x.creat + 0.1953 * x.gluc + 0.0954 * lnCRP
    - 0.0120 * x.lymph + 0.0268 * x.mcv + 0.3306 * x.rdw + 0.00188 * x.alp
    + 0.0554 * x.wbc + 0.0804 * x.age;
  const M = 1 - Math.exp(-1.51714 * Math.exp(xb) / 0.0076927);
  return Math.round((141.50 + Math.log(-0.00553 * Math.log(1 - M)) / 0.09165) * 100) / 100;
}

const sortedVisits = Object.values(visitMap).filter(v => v.date).sort((a, b) => a.date.localeCompare(b.date));

// «текущая оценка»: последнее доступное значение каждого маркера
const latestVal = {}, latestDate = {};
for (const v of sortedVisits) for (const k of KEYS) if (v.values[k] != null) { latestVal[k] = v.values[k]; latestDate[k] = v.date; }
const have = KEYS.filter(k => latestVal[k] != null);
const missing = KEYS.filter(k => latestVal[k] == null);
const today = new Date(Date.now() + 10 * 3600 * 1000).toISOString().slice(0, 10);
const curAge = ageAtDate(today);

let phenoage = null, drivers = [];
if (have.length === 9) {
  const pa = phenoAge({ ...latestVal, age: curAge });
  phenoage = {
    date: today,
    value: pa,
    chrono_age: Math.round(curAge * 10) / 10,
    delta: Math.round((pa - curAge) * 100) / 100,
    formula_version: FORMULA_VERSION,
    missing: [],
    oldest_marker_date: have.map(k => latestDate[k]).sort()[0],
  };
  // водопад: Хроно -> вклад каждого маркера -> PhenoAge. year<0 = маркер молодит.
  drivers.push({ label: 'Хроно', marker: null, years: phenoage.chrono_age, type: 'total' });
  for (const k of KEYS) {
    const swapped = { ...latestVal, age: curAge, [k]: REF[k] };
    const yearsIfHealthy = phenoAge(swapped);
    const contribution = Math.round((yearsIfHealthy - pa) * 100) / 100; // <0 = маркер молодит (замена на эталон состарила бы)
    drivers.push({
      label: PHENO[k].label, marker: k, years: contribution,
      type: contribution < 0 ? 'neg' : contribution > 0 ? 'pos' : 'flat',
      value: latestVal[k], measured_date: latestDate[k],
    });
  }
  drivers.push({ label: 'PhenoAge', marker: null, years: pa, type: 'total' });
} else {
  phenoage = { value: null, chrono_age: Math.round(curAge * 10) / 10, delta: null, missing, note: 'не хватает маркеров для расчёта' };
}

// история: из PhenoAge_Log (уже посчитано воркфлоу PhenoAge Calc)
const history = phenoLog
  .filter(r => num(r.phenoage) != null && d10(r.date))
  .map(r => ({
    date: d10(r.date), x: decYear(d10(r.date)),
    chrono_age: num(r.chrono_age), phenoage: num(r.phenoage), delta: num(r.delta),
    kind: /визит/.test(r.markers_used || '') ? 'visit' : /оценка/.test(r.markers_used || '') ? 'estimated' : 'current',
  }))
  .sort((a, b) => a.date.localeCompare(b.date));

// таблица биомаркеров: PhenoAge-9 всегда + прочие с последним значением и диапазоном
function stripPref(s) { return String(s || '').replace(/^PhenoAge\s*\/\s*/, '').trim(); }
const latestAny = {}, latestAnyDate = {}, latestAnyRange = {};
const visByDate = [...sortedVisits];
for (const v of visByDate) {
  for (const r of results.filter(x => x.Visit_ID === v.vid)) {
    const val = num(r.Value);
    if (val == null) continue;
    latestAny[r.Marker_ID] = val;
    latestAnyDate[r.Marker_ID] = v.date;
    latestAnyRange[r.Marker_ID] = { lab_min: num(r.Lab_Min), lab_max: num(r.Lab_Max) };
  }
}
const phenoIds = new Set(KEYS.map(k => PHENO[k].id));
const biomarkers = [];
for (const m of markers) {
  const id = m.Marker_ID;
  if (!id) continue;
  const val = latestAny[id];
  const optMin = num(m.Optimal_Min), optMax = num(m.Optimal_Max);
  const isPheno = phenoIds.has(id);
  if (val == null) continue;
  if (!isPheno && optMin == null && optMax == null) continue; // прочие — только если есть оптимум
  const rng = latestAnyRange[id] || {};
  biomarkers.push({
    marker_id: id,
    label: m.Name,
    group: stripPref(m.Category),
    pheno: isPheno,
    value: val,
    unit: m.Standard_Unit || null,
    measured_date: latestAnyDate[id] || null,
    lab_min: rng.lab_min, lab_max: rng.lab_max,
    opt_min: optMin, opt_max: optMax,
    in_lab_range: (rng.lab_min != null && rng.lab_max != null) ? (val >= rng.lab_min && val <= rng.lab_max) : null,
    in_opt_range: (optMin != null && optMax != null) ? (val >= optMin && val <= optMax) : null,
  });
}
biomarkers.sort((a, b) => (b.pheno - a.pheno) || String(a.group).localeCompare(String(b.group)) || String(a.label).localeCompare(String(b.label)));

// вне лабораторной нормы (последнее измерение каждого маркера)
const out_of_range = [];
for (const [id, val] of Object.entries(latestAny)) {
  const rng = latestAnyRange[id] || {};
  if (rng.lab_min == null && rng.lab_max == null) continue;
  const low = rng.lab_min != null && val < rng.lab_min;
  const high = rng.lab_max != null && val > rng.lab_max;
  if (!low && !high) continue;
  const m = markById[id] || {};
  out_of_range.push({
    label: m.Name || id, value: val, unit: m.Standard_Unit || null,
    ref: (rng.lab_min ?? '') + '–' + (rng.lab_max ?? ''), date: latestAnyDate[id] || null,
    flag: low ? 'ниже нормы' : 'выше нормы',
  });
}
out_of_range.sort((a, b) => String(b.date).localeCompare(String(a.date)));

// тренды ключевых маркеров по визитам
function series(rx) {
  return results
    .filter(r => rx.test((markById[r.Marker_ID] || {}).Name || ''))
    .map(r => ({ date: visitDate[r.Visit_ID] || d10(r.Visit_ID), value: num(r.Value) }))
    .filter(r => r.date && r.value != null)
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(-12);
}
const trends = { wbc: series(/лейкоциты|wbc/i), glucose: series(/глюкоза/i), crp: series(/с-реактивн|срб|crp/i), rdw: series(/rdw|ширина распред.*эритроцит/i) };

const rareOnce = KEYS.filter(k => {
  const cnt = sortedVisits.filter(v => v.values[k] != null).length;
  return cnt <= 1;
}).map(k => PHENO[k].label);

const result = {
  updated_at: new Date().toISOString(),
  phenoage,
  drivers,
  history,
  biomarkers,
  out_of_range,
  trends,
  data_note: rareOnce.length
    ? 'Маркеры с единственным измерением за всю историю (нет динамики): ' + rareOnce.join(', ') + '. Для тренда нужна полная панель в одной сдаче.'
    : null,
};

const sd = $getWorkflowStaticData('global');
sd.bioageDashboard = result;
sd.bioageComputedAt = result.updated_at;

return [{ json: result }];

const token = ($input.first().json.query || {}).token;
if (token !== 'ba_9Fw3nZp7Kd') { return [{ json: { error: 'forbidden' } }]; }
const sd = $getWorkflowStaticData('global');
const cached = sd.bioageDashboard;
if (!cached) { return [{ json: { error: 'no_data_yet', message: 'Кэш ещё не сформирован, подождите до часа.' } }]; }
return [{ json: cached }];

