  const high = rng.lab_max != null && val > rng.lab_max;
  if (!low && !high) continue;
  const m = markById[id] || {};
  out_of_range.push({
    label: m.Name || id, value: val, unit: m.Standard_Unit || null,
    ref: (rng.lab_min ?? '') + '–' + (rng.lab_max ?? ''), date: latestAnyDate[id] || null,
    flag: low ? 'ниже нормы' : 'выше нормы',
  });
}
out_of_range.sort((a, b) => String(b.date).localeCompare(String(a.date)));

